CREATE TABLE IF NOT EXISTS fuel_price_import (
  vendor        TEXT,
  store         TEXT,
  address       TEXT,
  city          TEXT,
  state         TEXT,
  retail_price  NUMERIC(6,3),
  our_price     NUMERIC(6,3),
  savings       NUMERIC(6,3),
  fee           NUMERIC(6,3),
  your_price    NUMERIC(6,3),
  your_savings  NUMERIC(6,3),
  insufficient_discount TEXT
);

TRUNCATE fuel_price_import;


















